/**
 * Zoho Embedded App SDK (Lightweight Loader & Interface)
 * Official SDK distribution reference for Zoho CRM Widgets.
 * https://js.zohocdn.com/crm/javascript/sdk/1.0.0/ZohoEmbededAppSDK.min.js
 */
(function (global) {
  if (global.ZOHO && global.ZOHO.embeddedApp) {
    return;
  }

  var eventHandlers = {};

  global.ZOHO = global.ZOHO || {};

  global.ZOHO.embeddedApp = {
    on: function (eventName, fn) {
      if (!eventHandlers[eventName]) {
        eventHandlers[eventName] = [];
      }
      eventHandlers[eventName].push(fn);
    },
    init: function () {
      // Send initialization message to parent window if in iframe
      if (window.parent && window.parent !== window) {
        window.parent.postMessage(JSON.stringify({ type: "ZOHO_WIDGET_INIT" }), "*");
      }
      return Promise.resolve();
    },
    _trigger: function (eventName, data) {
      if (eventHandlers[eventName]) {
        eventHandlers[eventName].forEach(function (handler) {
          try {
            handler(data);
          } catch (e) {
            console.error("Error executing event handler for " + eventName, e);
          }
        });
      }
    }
  };

  // Standard message listener for iframe communication with Zoho CRM parent window
  window.addEventListener("message", function (event) {
    try {
      var data = typeof event.data === "string" ? JSON.parse(event.data) : event.data;
      if (data && data.eventName) {
        global.ZOHO.embeddedApp._trigger(data.eventName, data.data || data);
      }
    } catch (e) {
      // Non-JSON or external message, ignore safely
    }
  });

})(window);
